def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    for _ in range(k):
        s = (a * s + b) % m

    return float(s)

scripts.luhn_checksum:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])
    digits = [int(d) for d in n]

    # Process from right to left
    total = 0
    for i in range(len(digits) - 1, -1, -1):
        digit = digits[i]
        position_from_right = len(digits) - 1 - i  # 0-indexed from right

        # Double every 2nd digit from the right (positions 1, 3, 5, ... from right)
        if position_from_right % 2 == 1:
            digit = digit * 2
            # If >= 10, add the digits together (same as subtracting 9)
            if digit >= 10:
                digit = digit - 9

        total += digit

    return float(total)

scripts.integer_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = 0
    for a, b in zip(A, B):
        total += a // b  # Integer division

    return float(total)

